import { Button } from '../ui';

export function Home({ navigation }: ScreenProps<'Home'>) {
  const [items, setItems] = useState<Product[]>([]);
  useEffect(() => {
    getProducts().then(r => setItems(r.body));
  }, []);
  const open = (id: string) => navigation.navigate('Product', { id });
