      <Button id="home/settings" label="Settings" onPress={() => navigation.navigate('Settings')} />
      <Picks items={items} onOpen={open} />
      <Popular items={items} onOpen={open} />
      <Deals items={items} onOpen={open} />
    </ScrollView>
  );
}

